std::string pattern = destination.string() + ".tmp-XXXXXX";
std::vector<char> temporary(pattern.begin(), pattern.end());
temporary.push_back('\0');
const int fd = mkstemp(temporary.data());
if (fd < 0)
    return false;

bool ok = fchmod(fd, S_IRUSR | S_IWUSR) == 0;
size_t written = 0;
while (ok && written < contents.size()) {
    const auto n = write(fd, contents.data() + written, contents.size() - written);
    if (n < 0 && errno == EINTR)
        continue;
    if (n <= 0) {
        ok = false;
        break;
    }
    written += static_cast<size_t>(n);
}

if (ok && fsync(fd) != 0)
    ok = false;
if (close(fd) != 0)
    ok = false;
if (ok && rename(temporary.data(), destination.c_str()) != 0)
    ok = false;

if (ok) {
    const int dir = open(parent.c_str(), O_RDONLY | O_DIRECTORY);
    if (dir < 0)
        ok = false;
    else {
        if (fsync(dir) != 0)
            ok = false;
        close(dir);
    }
}
if (!ok)
    unlink(temporary.data());

    if (study_files::write_private_file(destination, contents)) {
        std::fputs("write-confirmed\n", stdout);
        return 0;
    }
    std::fputs("write-not-confirmed\n", stdout);
    return 2;
} catch (...) {
    std::fputs("write-exception\n", stderr);
    return 3;
}
